window.TREE={"subject":"Area IV · Property Transactions","key":"tcp_area4_property","brand":"Terra Prep","area":"IV","law_asof":"2026-09-29","parts":[{"no":1,"name":"Area IV · Property Transactions","chs":["1-01","1-02","1-03"],"color":"--mint"}],"chs":[{"key":"1-01","part":1,"no":1,"name":"Nontaxable disposition of assets","grp":"A","nodes":[1]},{"key":"1-02","part":1,"no":2,"name":"Amount and character of gains and losses on asset disposition and netting process","grp":"B","nodes":[2,3,4,5,6,7]},{"key":"1-03","part":1,"no":3,"name":"Related party transactions, including imputed interest","grp":"C","nodes":[8,9,10,11]}],"nodes":[{"no":1,"part":1,"ch":1,"title":"Like-kind exchange / involuntary conversion","name":"Like-kind exchange / involuntary conversion","vol":8,"q":8,"cs":0,"law":0,"grp":"A"},{"no":2,"part":1,"ch":2,"title":"Character of gain/loss","name":"Character of gain/loss","vol":2,"q":2,"cs":0,"law":0,"grp":"B"},{"no":3,"part":1,"ch":2,"title":"Section 1231 netting","name":"Section 1231 netting","vol":4,"q":4,"cs":0,"law":0,"grp":"B"},{"no":4,"part":1,"ch":2,"title":"Section 1245/1250 recapture","name":"Section 1245/1250 recapture","vol":1,"q":1,"cs":0,"law":0,"grp":"B"},{"no":5,"part":1,"ch":2,"title":"Unrecaptured Section 1250 gain","name":"Unrecaptured Section 1250 gain","vol":3,"q":3,"cs":0,"law":0,"grp":"B"},{"no":6,"part":1,"ch":2,"title":"Section 1244 stock loss","name":"Section 1244 stock loss","vol":2,"q":2,"cs":0,"law":0,"grp":"B"},{"no":7,"part":1,"ch":2,"title":"Installment sale gain","name":"Installment sale gain","vol":3,"q":3,"cs":0,"law":0,"grp":"B"},{"no":8,"part":1,"ch":3,"title":"Related parties definition","name":"Related parties definition","vol":2,"q":2,"cs":0,"law":0,"grp":"C"},{"no":9,"part":1,"ch":3,"title":"Ownership percentage calc","name":"Ownership percentage calc","vol":4,"q":4,"cs":0,"law":0,"grp":"C"},{"no":10,"part":1,"ch":3,"title":"Subsequent disposition to unrelated party","name":"Subsequent disposition to unrelated party","vol":2,"q":2,"cs":0,"law":0,"grp":"C"},{"no":11,"part":1,"ch":3,"title":"Imputed interest","name":"Imputed interest","vol":2,"q":2,"cs":0,"law":0,"grp":"C"}],"stat":{"parts":1,"chs":3,"nodes":11,"q":33}};
window.QBANK={"1":[{"i":"TCP-IV-A-0001","t":"Lee Ford exchanges land held for investment, with an adjusted basis of $200,000 and a fair market value of $500,000, for other investment land worth $450,000 plus $50,000 in cash, in a qualifying like-kind exchange. How much of his realized gain is deferred?","mc":{"s":"Lee Ford exchanges land held for investment, with an adjusted basis of $200,000 and a fair market value of $500,000, for other investment land worth $450,000 plus $50,000 in cash, in a qualifying like-kind exchange. How much of his realized gain is deferred?","d":"","o":["$50,000","$200,000","$250,000","$300,000"],"a":3,"cite":"IRC §1031(a); IRC §1031(b); IRC §1031(d)","rat":"Realized gain = $500,000 - $200,000 = $300,000.","ex":["This is the recognized gain, which equals the boot, not the deferred gain.","Reports the adjusted basis as the deferred gain.","Realized gain = $500,000 - $200,000 = $300,000. The cash is boot, so gain of $50,000 is recognized. The deferred gain is $300,000 - $50,000 = $250,000.","This is the total realized gain, without reducing it for the gain recognized on the boot."],"wt":["trap","calc","","trap"],"tags":{"area":"IV","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"In a like-kind exchange with boot, gain is recognized to the extent of boot received; the rest of the realized gain is deferred.","from":"2026-01-01","calc":1,"steps":["Realized gain = 500,000 - 200,000 = $300,000","Recognized gain = boot = 50,000","Deferred = $250,000"]}},{"i":"TCP-IV-A-0002","t":"Neal Ito exchanges an office building with an adjusted basis of $250,000 and a fair market value of $600,000, subject to a $200,000 mortgage, for another office building worth $500,000 subject to a $100,000 mortgage. No cash changes hands. The exchange otherwise qualifies as like-kind. What gain does Neal recognize?","mc":{"s":"Neal Ito exchanges an office building with an adjusted basis of $250,000 and a fair market value of $600,000, subject to a $200,000 mortgage, for another office building worth $500,000 subject to a $100,000 mortgage. No cash changes hands. The exchange otherwise qualifies as like-kind. What gain does Neal recognize?","d":"","o":["$0","$25,000","$50,000","$100,000"],"a":4,"cite":"IRC §1031(d); IRC §1031(b); Reg. §1.1031(d)-2","rat":"Neal's liabilities decreased from $200,000 to $100,000, so he is treated as receiving $100,000 of boot.","ex":["Assumes nonrecognition because no cash was received. Net liability relief is boot.","Uses a quarter of the net liability relief.","Treats only half of the net liability relief as boot.","Neal's liabilities decreased from $200,000 to $100,000, so he is treated as receiving $100,000 of boot. He has no offsetting cash paid or new property boot, and the realized gain ($350,000) is larger, so recognized gain is $100,000."],"wt":["concept","calc","calc",""],"tags":{"area":"IV","group":"A","skill":"Application","diff":3},"asof":"2026-09-29","rl":"Net liability relief in a like-kind exchange is treated as boot, and gain is recognized to that extent.","from":"2026-01-01","calc":1,"steps":["Net liability relief = 200,000 - 100,000 = $100,000","Realized gain = 600,000 - 250,000 = $350,000","Recognized = lesser = $100,000"]}},{"i":"TCP-IV-A-0003","t":"In 2026 a city condemns Jan Roe's rental building, which has an adjusted basis of $150,000. She receives $400,000 and in 2026 buys a similar building for $340,000 and elects nonrecognition. How much of her realized gain is deferred?","mc":{"s":"In 2026 a city condemns Jan Roe's rental building, which has an adjusted basis of $150,000. She receives $400,000 and in 2026 buys a similar building for $340,000 and elects nonrecognition. How much of her realized gain is deferred?","d":"","o":["$0","$60,000","$190,000","$250,000"],"a":3,"cite":"IRC §1033(a)(2); IRC §1033(b); Reg. §1.1033(a)-2","rat":"Realized gain = $400,000 - $150,000 = $250,000.","ex":["Assumes the entire gain is recognized because the replacement cost was less than the award.","This is the recognized gain, not the deferred gain.","Realized gain = $400,000 - $150,000 = $250,000. Gain is recognized to the extent proceeds are not reinvested: $400,000 - $340,000 = $60,000. The deferred gain is $250,000 - $60,000 = $190,000.","This is the entire realized gain, without reducing it for the gain recognized."],"wt":["concept","trap","","trap"],"tags":{"area":"IV","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"In an involuntary conversion, gain is recognized only to the extent proceeds exceed the cost of qualifying replacement property.","from":"2026-01-01","calc":1,"steps":["Realized gain = 400,000 - 150,000 = $250,000","Recognized = 400,000 - 340,000 = $60,000","Deferred = $190,000"]}},{"i":"TCP-IV-A-0004","t":"Gwen Park owns investment land with a basis of $200,000 and a fair market value of $800,000. She can sell it for cash or exchange it in a qualifying like-kind exchange in which she receives replacement land plus $100,000 of cash. Assume gain is taxed at 23.8% in either case. How much federal tax does the exchange defer compared with the sale?","mc":{"s":"Gwen Park owns investment land with a basis of $200,000 and a fair market value of $800,000. She can sell it for cash or exchange it in a qualifying like-kind exchange in which she receives replacement land plus $100,000 of cash. Assume gain is taxed at 23.8% in either case. How much federal tax does the exchange defer compared with the sale?","d":"","o":["$23,800","$47,600","$95,200","$119,000"],"a":4,"cite":"IRC §1031(a); IRC §1031(b); IRC §1(h)","rat":"A sale triggers tax on the whole $600,000 gain: $142,800.","ex":["This is the tax still due on the boot, not the deferral.","Doubles the tax on the boot.","Subtracts the tax on the boot twice.","A sale triggers tax on the whole $600,000 gain: $142,800. The exchange triggers tax only on the $100,000 of boot: $23,800. The exchange defers $119,000."],"wt":["trap","calc","calc",""],"tags":{"area":"IV","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A like-kind exchange defers tax on the gain not represented by boot.","from":"2026-01-01","calc":1,"steps":["Tax if sold = 23.8% x $600,000 = $142,800","Tax on exchange = 23.8% x 100,000 = $23,800","Tax deferred = $119,000"]}},{"i":"TCP-IV-A-0005","t":"On December 15, 2026, Otto Blum, a calendar-year individual who does not extend his tax return, transfers investment land in a deferred like-kind exchange through a qualified intermediary. He wants to acquire the replacement land as late as possible. What is the last day on which he may receive the replacement property to qualify?","mc":{"s":"On December 15, 2026, Otto Blum, a calendar-year individual who does not extend his tax return, transfers investment land in a deferred like-kind exchange through a qualified intermediary. He wants to acquire the replacement land as late as possible. What is the last day on which he may receive the replacement property to qualify?","d":"","o":["June 13, 2027, which is 180 days after the date of transfer","January 29, 2027, which is 45 days after the date of transfer","December 31, 2027, the end of the calendar year that follows","April 15, 2027, the return due date, which comes before day 180"],"a":4,"cite":"IRC §1031(a)(3); Reg. §1.1031(k)-1(b); Reg. §1.1031(k)-1(b)(2)","rat":"The exchange period ends on the earlier of 180 days after the transfer or the due date of the return, including extensions, for the year of the transfer.","ex":["The 180-day period is cut short by the return due date because he does not extend the return.","The 45-day period is the deadline to identify replacement property, not to receive it.","There is no calendar-year deadline. The period ends at the earlier of 180 days or the return due date.","The exchange period ends on the earlier of 180 days after the transfer or the due date of the return, including extensions, for the year of the transfer."],"wt":["limit","trap","concept",""],"tags":{"area":"IV","group":"A","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Replacement property must be identified within 45 days and received by the earlier of 180 days or the due date of the return, including extensions, for the transfer year.","from":"2026-01-01","calc":1,"steps":["45th day after December 15, 2026 is January 29, 2027 (identification deadline)","180th day is June 13, 2027","Due date of the 2026 return, without extension, is April 15, 2027, which is earlier"]}},{"i":"TCP-IV-A-0006","t":"In 2026 a state condemns a warehouse that Cole Reed holds for business use, and he realizes a gain on receipt of the award in 2026. Cole is a calendar-year taxpayer. What is the last day of the replacement period for the warehouse if he wants to defer the gain?","mc":{"s":"In 2026 a state condemns a warehouse that Cole Reed holds for business use, and he realizes a gain on receipt of the award in 2026. Cole is a calendar-year taxpayer. What is the last day of the replacement period for the warehouse if he wants to defer the gain?","d":"","o":["December 31, 2029, three years after the year the gain was first realized","December 31, 2028, two years after the end of the year the gain was realized","December 31, 2027, one year after the year the gain was first realized","December 31, 2030, four years after the year the gain was realized"],"a":1,"cite":"IRC §1033(a)(2)(B); IRC §1033(g)(4); Reg. §1.1033(a)-2(c)","rat":"For condemned real property held for business or investment, the replacement period ends three years after the close of the first year in which any gain is realized.","ex":["For condemned real property held for business or investment, the replacement period ends three years after the close of the first year in which any gain is realized.","Two years is the general period, but condemned business real property gets three.","There is no one-year replacement period for a condemnation of business real property.","The extended period for condemned real property is three years, not four."],"wt":["","limit","concept","limit"],"tags":{"area":"IV","group":"A","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"The replacement period is two years after the year of first gain, extended to three years for condemned business or investment real property.","from":"2026-01-01"}},{"i":"TCP-IV-A-0007","t":"Ola Peretz exchanges investment land with a basis of $200,000 and a value of $700,000 for other investment land worth $700,000 (like-kind, no boot). Plan 1: she exchanges directly with her brother, who owns the other land and who gives up land with a basis of $500,000. Fourteen months later her brother sells the land he received from Ola to an unrelated buyer for $700,000. Plan 2: she exchanges through a qualified intermediary with an unrelated party, and that party sells Ola's former land 14 months later for $700,000. Assume no exception to the two-year rule applies. Which statement about the gain Ola recognizes on her exchange is correct?","mc":{"s":"Ola Peretz exchanges investment land with a basis of $200,000 and a value of $700,000 for other investment land worth $700,000 (like-kind, no boot). Plan 1: she exchanges directly with her brother, who owns the other land and who gives up land with a basis of $500,000. Fourteen months later her brother sells the land he received from Ola to an unrelated buyer for $700,000. Plan 2: she exchanges through a qualified intermediary with an unrelated party, and that party sells Ola's former land 14 months later for $700,000. Assume no exception to the two-year rule applies. Which statement about the gain Ola recognizes on her exchange is correct?","d":"","o":["Plan 1: no gain recognized; Plan 2: no gain recognized, because both exchanges are of like-kind property","Plan 1: $500,000 recognized in the year of her brother's sale; Plan 2: no gain recognized","Plan 1: $500,000 recognized in the year of the exchange; Plan 2: no gain recognized","Plan 1: $500,000 recognized in the year of her brother's sale; Plan 2: $500,000 recognized in the year of the exchange"],"a":2,"cite":"IRC §1031(f)(1); IRC §1031(f)(3); IRC §267(b)","rat":"Ola's realized gain is $500,000 in both plans.","ex":["Being like-kind is not enough for the related party exchange. A disposition by the related party within two years triggers the deferred gain.","Ola's realized gain is $500,000 in both plans. If a related person disposes of the property received within two years, the deferral is lost and Ola recognizes the deferred gain in the year of the second disposition, so Plan 1 gives $500,000 in the year of the brother's sale. Plan 2 is an exchange with an unrelated party, so the sale by that party has no effect on Ola.","The gain is recognized when the related person disposes of the property (the year of the brother's sale), not on the exchange date. If the property were held two years, Ola would have kept the deferral.","An exchange through a qualified intermediary with an unrelated party is a normal like-kind exchange. The unrelated party's later sale does not affect Ola."],"wt":["concept","","trap","concept"],"tags":{"area":"IV","group":"A","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Gain deferred in a like-kind exchange with a related person is recognized if either party disposes of the property within two years, in the year of the disposition.","from":"2026-01-01","calc":1,"steps":["Realized gain = 700,000 - 200,000 = 500,000 in both plans","Plan 1: related party exchange; brother's sale within 2 years (14 months) triggers recognition of 500,000 in that year","Plan 2: exchange with an unrelated party; later sale is irrelevant to Ola, so no gain is recognized"]}},{"i":"TCP-IV-A-0008","t":"Lena Ortiz's husband died on March 10, 2025. They had owned their main home and lived in it for ten years, as joint tenants with rights of survivorship, and their combined basis in it was $200,000. Its value on the date of death was $600,000. Lena has not remarried and will not remarry. She can sell the home for a net amount realized of $800,000 either on March 5, 2027 or on March 20, 2027. Assume she has owned and lived in the home for two of the last five years at each date and that her husband's half was included in his estate. How much more gain does she recognize by selling on March 20, 2027 than on March 5, 2027?","mc":{"s":"Lena Ortiz's husband died on March 10, 2025. They had owned their main home and lived in it for ten years, as joint tenants with rights of survivorship, and their combined basis in it was $200,000. Its value on the date of death was $600,000. Lena has not remarried and will not remarry. She can sell the home for a net amount realized of $800,000 either on March 5, 2027 or on March 20, 2027. Assume she has owned and lived in the home for two of the last five years at each date and that her husband's half was included in his estate. How much more gain does she recognize by selling on March 20, 2027 than on March 5, 2027?","d":"","o":["$0","$150,000","$250,000","$400,000"],"a":2,"cite":"IRC §121(b)(4); IRC §1014(a); IRC §2040(b)","rat":"Only her husband's half of the home gets a stepped-up basis, so her basis is $100,000 + $300,000 = $400,000 and the gain is $400,000.","ex":["Assumes the exclusion covers the gain on both dates. The $250,000 exclusion after two years is less than her $400,000 gain.","Only her husband's half of the home gets a stepped-up basis, so her basis is $100,000 + $300,000 = $400,000 and the gain is $400,000. A sale by March 10, 2027 (within two years of death) still allows the $500,000 exclusion, so no gain is taxable. A sale after that date allows only $250,000, leaving $150,000 taxable. The difference is $150,000.","This is the difference between the two exclusion limits. The extra gain recognized is limited to the gain that exceeds $250,000, which is smaller here.","This is her entire gain of $400,000. A sale on either date qualifies for some exclusion, so not all of it is recognized."],"wt":["concept","","trap","concept"],"tags":{"area":"IV","group":"A","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"A surviving spouse who has not remarried may use the $500,000 exclusion on a sale within two years of the spouse's death, and only the $250,000 exclusion later; the deceased spouse's half of jointly held property gets a stepped-up basis.","from":"2026-01-01","calc":1,"steps":["Basis = 200,000 / 2 + 600,000 / 2 = 400,000 (only the husband's half is stepped up); gain = 800,000 - 400,000 = 400,000","March 5, 2027 is within two years of March 10, 2025: exclusion 500,000, taxable gain = 0","March 20, 2027 is after two years: exclusion 250,000, taxable gain = 400,000 - 250,000 = 150,000","Difference = 150,000"]}}],"2":[{"i":"TCP-IV-B-0001","t":"Each of the following sales occurred in 2026 at a gain. Which sale produces long-term capital gain for the seller?","mc":{"s":"Each of the following sales occurred in 2026 at a gain. Which sale produces long-term capital gain for the seller?","d":"","o":["Inventory held for resale by a retailer for 13 months and then sold at a gain","Stock held as an investment for 13 months and then sold at a gain","Machinery used in a business for 8 months and then sold at a gain","A copyright on a novel held for 13 months by the author who created it"],"a":2,"cite":"IRC §1221(a); IRC §1222(3); IRC §1231(b)","rat":"Investment stock is a capital asset, and holding it more than one year makes the gain long-term.","ex":["Inventory is not a capital asset, so the gain is ordinary income.","Investment stock is a capital asset, and holding it more than one year makes the gain long-term.","Machinery is depreciable business property, and held less than a year the gain is ordinary.","A self-created copyright is excluded from capital assets, so the sale generates ordinary income."],"wt":["concept","","concept","concept"],"tags":{"area":"IV","group":"B","skill":"Application","diff":1},"asof":"2026-09-29","rl":"Capital assets held more than one year produce long-term capital gain; inventory, depreciable business property held short term, and self-created copyrights do not.","from":"2026-01-01"}},{"i":"TCP-IV-B-0010","t":"Bo Weiss, a sole proprietor, sold all of the assets of his business in 2026. Inventory sold for $60,000 (basis $40,000). Equipment sold for $90,000; it cost $100,000 and depreciation of $70,000 had been claimed. Land held for business use for many years sold for $50,000 (basis $30,000). Self-created goodwill, with no basis, was sold for $100,000. How much of the total gain is ordinary income?","mc":{"s":"Bo Weiss, a sole proprietor, sold all of the assets of his business in 2026. Inventory sold for $60,000 (basis $40,000). Equipment sold for $90,000; it cost $100,000 and depreciation of $70,000 had been claimed. Land held for business use for many years sold for $50,000 (basis $30,000). Self-created goodwill, with no basis, was sold for $100,000. How much of the total gain is ordinary income?","d":"","o":["$20,000","$60,000","$80,000","$200,000"],"a":3,"cite":"IRC §1221(a)(1); IRC §1245(a); IRC §1231(b); IRC §1060","rat":"Inventory gain of $20,000 is ordinary.","ex":["Counts only the inventory and misses the recapture on the equipment.","Counts only the recapture on the equipment and misses the inventory gain.","Inventory gain of $20,000 is ordinary. The equipment gain is $90,000 - $30,000 = $60,000, all of which is depreciation recapture (the lesser of gain and depreciation of $70,000) and ordinary. The land and goodwill gains are not ordinary. Total ordinary $80,000.","Treats the whole gain as ordinary income. Land and goodwill produce section 1231 or capital gain."],"wt":["concept","concept","","concept"],"tags":{"area":"IV","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"On a sale of a business, inventory gain and depreciation recapture are ordinary; land and self-created goodwill are section 1231 or capital.","from":"2026-01-01","calc":1,"steps":["Inventory gain = $20,000 (ordinary)","Equipment gain = $60,000; recapture = $60,000 (ordinary)","Ordinary total = $80,000"]}}],"3":[{"i":"TCP-IV-B-0002","t":"Pia Voss has a net gain of $100,000 for 2026 from netting her sales of depreciable business property and business real estate held more than one year. In the previous five years the same netting produced net losses of $40,000 that have not been offset by later gains. How much of the 2026 net gain is treated as long-term capital gain?","mc":{"s":"Pia Voss has a net gain of $100,000 for 2026 from netting her sales of depreciable business property and business real estate held more than one year. In the previous five years the same netting produced net losses of $40,000 that have not been offset by later gains. How much of the 2026 net gain is treated as long-term capital gain?","d":"","o":["$0","$40,000","$60,000","$100,000"],"a":3,"cite":"IRC §1231(c); IRC §1231(a)(1); Form 4797 instructions","rat":"Net section 1231 gain is recharacterized as ordinary income to the extent of nonrecaptured net section 1231 losses in the five preceding years: $40,000.","ex":["Assumes the whole gain is recaptured as ordinary income. Only prior net losses are recaptured.","Treats only the prior losses as capital gain.","Net section 1231 gain is recharacterized as ordinary income to the extent of nonrecaptured net section 1231 losses in the five preceding years: $40,000. The remaining $100,000 - $40,000 = $60,000 is long-term capital gain.","Treats the entire gain as capital and ignores the five-year lookback for prior losses."],"wt":["concept","concept","","concept"],"tags":{"area":"IV","group":"B","skill":"Application","diff":3},"asof":"2026-09-29","rl":"Net section 1231 gain is ordinary to the extent of net section 1231 losses in the prior five years not yet recaptured.","from":"2026-01-01","calc":1,"steps":["Ordinary income = 40,000","Long-term capital gain = 100,000 - 40,000 = $60,000"]}},{"i":"TCP-IV-B-0003","t":"Sol Ferro, a sole proprietor, sold two business assets held for more than one year in 2026: one at a gain of $80,000 and one at a loss of $130,000, both on depreciable business property. He has no capital transactions and no prior netting losses. By how much do these sales reduce his 2026 ordinary income?","mc":{"s":"Sol Ferro, a sole proprietor, sold two business assets held for more than one year in 2026: one at a gain of $80,000 and one at a loss of $130,000, both on depreciable business property. He has no capital transactions and no prior netting losses. By how much do these sales reduce his 2026 ordinary income?","d":"","o":["$3,000","$50,000","$80,000","$130,000"],"a":2,"cite":"IRC §1231(a)(2); IRC §1231(a)(1); Form 4797 instructions","rat":"Section 1231 gains and losses are netted.","ex":["Applies the capital loss limitation. A net section 1231 loss is ordinary and is not limited to $3,000.","Section 1231 gains and losses are netted. The net loss of $130,000 - $80,000 = $50,000 is an ordinary loss, fully deductible against other income, and not subject to the capital loss limit.","Uses only the gain and ignores the loss.","Uses only the loss and ignores the gain that offsets it in the netting."],"wt":["limit","","concept","concept"],"tags":{"area":"IV","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Net section 1231 losses are ordinary and fully deductible; net section 1231 gains are treated as long-term capital gain.","from":"2026-01-01","calc":1,"steps":["Net section 1231 result = 80,000 - 130,000 = -$50,000","Ordinary loss = $50,000"]}},{"i":"TCP-IV-B-0011","t":"Ray Odell has a net gain of $40,000 for 2026 from sales of business property held more than one year, with no prior netting losses, and a net short-term capital loss of $25,000 on the sale of stock. He has no other capital items. What is his net capital gain for 2026?","mc":{"s":"Ray Odell has a net gain of $40,000 for 2026 from sales of business property held more than one year, with no prior netting losses, and a net short-term capital loss of $25,000 on the sale of stock. He has no other capital items. What is his net capital gain for 2026?","d":"","o":["$15,000","$25,000","$40,000","$65,000"],"a":1,"cite":"IRC §1231(a)(1); IRC §1222(11); IRC §1211(b)","rat":"A net section 1231 gain is treated as long-term capital gain.","ex":["A net section 1231 gain is treated as long-term capital gain. It is netted with the short-term capital loss: $40,000 - $25,000 = $15,000 of net long-term capital gain.","Uses the short-term loss amount as if it were a gain.","Ignores the short-term capital loss, which offsets the long-term gain in the netting.","Adds the loss to the gain instead of subtracting it."],"wt":["","trap","concept","calc"],"tags":{"area":"IV","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Net section 1231 gain is treated as long-term capital gain and is netted with other capital gains and losses.","from":"2026-01-01","calc":1,"steps":["Net long-term capital gain = 40,000 - 25,000 = $15,000"]}},{"i":"TCP-IV-B-0015","t":"Kurt Lund had a net loss of $30,000 from sales of business assets held more than a year in 2025 that he deducted as an ordinary loss, and he had no other such net losses or gains in the prior five years. In 2026 and 2027 he plans to sell two business assets held more than a year: Asset X at a $100,000 gain and Asset Y at a $70,000 loss. Plan 1: sell both in 2026. Plan 2: sell X in 2026 and Y in 2027. Plan 3: sell Y in 2026 and X in 2027. Assume he is in the 37% bracket on ordinary income in both years, long-term capital gain is taxed at 20%, and ignore later years. Which plan gives the lowest total federal tax for 2026 and 2027?","mc":{"s":"Kurt Lund had a net loss of $30,000 from sales of business assets held more than a year in 2025 that he deducted as an ordinary loss, and he had no other such net losses or gains in the prior five years. In 2026 and 2027 he plans to sell two business assets held more than a year: Asset X at a $100,000 gain and Asset Y at a $70,000 loss. Plan 1: sell both in 2026. Plan 2: sell X in 2026 and Y in 2027. Plan 3: sell Y in 2026 and X in 2027. Assume he is in the 37% bracket on ordinary income in both years, long-term capital gain is taxed at 20%, and ignore later years. Which plan gives the lowest total federal tax for 2026 and 2027?","d":"","o":["Plan 1, with total tax of $11,100","Plan 3, with a net total tax saving of $25,900","Plans 1 and 3 equally, each with total tax of $11,100, and both lower than Plan 2","Plan 2, with a net total tax saving of $800"],"a":4,"cite":"IRC §1231(c); IRC §1231(a); IRC §1(h)","rat":"In 2026 the $100,000 net gain is $30,000 ordinary (recapture of the 2025 loss) and $70,000 capital gain: $11,100 + $14,000 = $25,100.","ex":["Plan 1 nets to a $30,000 gain, all of it ordinary because of the 2025 loss recapture, for $11,100. Plan 2 is lower.","The 2026 ordinary loss saves $25,900, but the loss adds to the nonrecaptured losses, so the 2027 gain of $100,000 is all ordinary and costs $37,000. Total tax is $11,100.","Plans 1 and 3 do give $11,100, but Plan 2 is lower because it turns $70,000 of gain into capital gain in 2026 and uses the 2027 loss as an ordinary deduction.","In 2026 the $100,000 net gain is $30,000 ordinary (recapture of the 2025 loss) and $70,000 capital gain: $11,100 + $14,000 = $25,100. In 2027 the $70,000 net loss is ordinary and saves $25,900. Net is a saving of $800, against $11,100 of tax in Plan 1."],"wt":["concept","trap","concept",""],"tags":{"area":"IV","group":"B","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"Net section 1231 gain is treated as ordinary income to the extent of net section 1231 losses in the prior five years that have not been recaptured, so the timing of gains and losses across years changes their character.","from":"2026-01-01","calc":1,"steps":["Plan 1: 2026 net gain 30,000, ordinary by recapture of the 2025 loss: tax = 30,000 x 37% = 11,100","Plan 2: 2026 net gain 100,000 = 30,000 ordinary + 70,000 capital: tax = 11,100 + 14,000 = 25,100; 2027 net loss 70,000 ordinary: saving 25,900; total = 25,100 - 25,900 = -800","Plan 3: 2026 net loss 70,000 saves 25,900; 2027 gain 100,000 is ordinary up to nonrecaptured losses 30,000 + 70,000 = 100,000: tax 37,000; total = 11,100","Lowest is Plan 2 (a net saving of 800)"]}}],"4":[{"i":"TCP-IV-B-0004","t":"Rae Bolt sold a machine used in her business for $85,000. She bought it for $100,000 and had claimed $70,000 of depreciation. How much of her gain is ordinary income from depreciation recapture?","mc":{"s":"Rae Bolt sold a machine used in her business for $85,000. She bought it for $100,000 and had claimed $70,000 of depreciation. How much of her gain is ordinary income from depreciation recapture?","d":"","o":["$0","$15,000","$55,000","$70,000"],"a":3,"cite":"IRC §1245(a)(1); IRC §1245(a)(2); Form 4797 instructions","rat":"Adjusted basis is $100,000 - $70,000 = $30,000, so the gain is $85,000 - $30,000 = $55,000.","ex":["Treats the gain as section 1231 gain only. Depreciation recapture on machinery is ordinary income.","Subtracts the depreciation from the selling price instead of measuring gain over adjusted basis.","Adjusted basis is $100,000 - $70,000 = $30,000, so the gain is $85,000 - $30,000 = $55,000. Recapture on machinery is the lesser of the gain or the depreciation taken, so all $55,000 is ordinary income.","Uses the total depreciation taken, which exceeds the gain realized."],"wt":["concept","calc","","limit"],"tags":{"area":"IV","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Recapture on section 1245 property is ordinary income equal to the lesser of the gain or depreciation taken.","from":"2026-01-01","calc":1,"steps":["Adjusted basis = 100,000 - 70,000 = $30,000","Gain = 85,000 - $30,000 = $55,000","Ordinary recapture = lesser of $55,000 and 70,000 = $55,000"]}}],"5":[{"i":"TCP-IV-B-0005","t":"Ana Diaz, whose ordinary rate is 37%, sold a rental building for $600,000. She bought it for $500,000 and had claimed $120,000 of straight-line depreciation. The gain is a net gain on business real estate held more than one year. Assume the part of the gain equal to prior straight-line depreciation is taxed at a maximum of 25% and the rest of the gain at 20%. What is the federal income tax on the sale?","mc":{"s":"Ana Diaz, whose ordinary rate is 37%, sold a rental building for $600,000. She bought it for $500,000 and had claimed $120,000 of straight-line depreciation. The gain is a net gain on business real estate held more than one year. Assume the part of the gain equal to prior straight-line depreciation is taxed at a maximum of 25% and the rest of the gain at 20%. What is the federal income tax on the sale?","d":"","o":["$44,000","$50,000","$55,000","$81,400"],"a":2,"cite":"IRC §1(h)(1)(E); IRC §1(h)(6); IRC §1250","rat":"The gain is $600,000 - ($500,000 - $120,000) = $220,000.","ex":["Taxes all of the gain at 20% and ignores the 25% rate on unrecaptured section 1250 gain.","The gain is $600,000 - ($500,000 - $120,000) = $220,000. The unrecaptured section 1250 gain, $120,000, is taxed at 25% ($30,000) and the other $100,000 at 20% ($20,000). Total $50,000.","Taxes all of the gain at 25%, though only the depreciation portion is taxed at that rate.","Taxes the whole gain at the ordinary rate. Straight-line depreciation on a building is not ordinary recapture."],"wt":["concept","","concept","concept"],"tags":{"area":"IV","group":"B","skill":"Application","diff":3},"asof":"2026-09-29","rl":"Gain on real property up to prior straight-line depreciation is unrecaptured section 1250 gain, taxed at a maximum 25%; the rest is taxed at 0/15/20%.","from":"2026-01-01","calc":1,"steps":["Gain = $220,000","Unrecaptured section 1250 gain = 120,000 x 25% = $30,000","Remaining $100,000 x 20% = $20,000","Total = $50,000"]}},{"i":"TCP-IV-B-0006","t":"Tess Kim sold a rental building at a gain of $90,000. She had claimed $120,000 of straight-line depreciation on it, and she has no other capital or business-property items. What part of her gain is taxed at the 25% maximum rate because of prior straight-line depreciation?","mc":{"s":"Tess Kim sold a rental building at a gain of $90,000. She had claimed $120,000 of straight-line depreciation on it, and she has no other capital or business-property items. What part of her gain is taxed at the 25% maximum rate because of prior straight-line depreciation?","d":"","o":["$30,000","$45,000","$90,000","$120,000"],"a":3,"cite":"IRC §1(h)(6); IRC §1(h)(1)(E); Sch D Tax Worksheet instructions","rat":"The part of the gain equal to prior straight-line depreciation is taxed at up to 25%, but it cannot exceed the gain itself.","ex":["Uses the depreciation in excess of the gain rather than the gain itself.","Uses half of the gain, which has no basis in the rule.","The part of the gain equal to prior straight-line depreciation is taxed at up to 25%, but it cannot exceed the gain itself. The gain is $90,000, which is less than the $120,000 of depreciation, so all $90,000 is taxed at that rate.","Uses the total depreciation, which exceeds the gain realized."],"wt":["calc","calc","","limit"],"tags":{"area":"IV","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Unrecaptured section 1250 gain is the lesser of the gain on the sale and the straight-line depreciation taken, taxed at a maximum of 25%.","from":"2026-01-01","calc":1,"steps":["Gain = 90,000; depreciation = 120,000","Unrecaptured section 1250 gain = lesser = $90,000"]}},{"i":"TCP-IV-B-0012","t":"Pete Nolan, whose ordinary rate is 35%, sold a rental building for $380,000 that he had bought for $300,000. He had claimed $90,000 of straight-line depreciation. Assume the part of the gain equal to prior straight-line depreciation is taxed at 25% and other long-term gain at 20%. How much of his federal tax on the sale is attributable to the part taxed at 25%?","mc":{"s":"Pete Nolan, whose ordinary rate is 35%, sold a rental building for $380,000 that he had bought for $300,000. He had claimed $90,000 of straight-line depreciation. Assume the part of the gain equal to prior straight-line depreciation is taxed at 25% and other long-term gain at 20%. How much of his federal tax on the sale is attributable to the part taxed at 25%?","d":"","o":["$9,000","$13,500","$18,000","$22,500"],"a":4,"cite":"IRC §1(h)(1)(E); IRC §1(h)(6); IRC §1250","rat":"The gain is $380,000 - ($300,000 - $90,000) = $170,000.","ex":["Taxes the depreciation portion at 10%, the wrong rate.","Taxes the depreciation portion at 15%, the wrong rate.","Taxes the depreciation portion at 20%, the rate for other long-term gain.","The gain is $380,000 - ($300,000 - $90,000) = $170,000. The unrecaptured section 1250 gain is the lesser of that gain and the depreciation, $90,000, taxed at 25%: $22,500."],"wt":["limit","limit","concept",""],"tags":{"area":"IV","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Unrecaptured section 1250 gain, the gain up to prior straight-line depreciation, is taxed at a maximum of 25%.","from":"2026-01-01","calc":1,"steps":["Gain = $170,000","Unrecaptured section 1250 gain = lesser of $170,000 and 90,000 = $90,000","Tax at 25% = $22,500"]}}],"6":[{"i":"TCP-IV-B-0007","t":"Mia and Jon Kade, who file jointly, bought newly issued stock in a small business corporation directly from the corporation for $150,000 cash in 2020, and the stock qualifies as small business stock for ordinary loss treatment. In 2026 they sell it for $30,000. They have no other capital transactions. Assume the ordinary loss limit on a joint return is $100,000. How much of the loss is an ordinary loss?","mc":{"s":"Mia and Jon Kade, who file jointly, bought newly issued stock in a small business corporation directly from the corporation for $150,000 cash in 2020, and the stock qualifies as small business stock for ordinary loss treatment. In 2026 they sell it for $30,000. They have no other capital transactions. Assume the ordinary loss limit on a joint return is $100,000. How much of the loss is an ordinary loss?","d":"","o":["$20,000","$50,000","$60,000","$100,000"],"a":4,"cite":"IRC §1244(a); IRC §1244(b); Pub 550","rat":"The loss is $150,000 - $30,000 = $120,000.","ex":["Uses the excess as the ordinary loss. The excess is the capital loss.","Uses the $50,000 limit that applies to a single return.","Treats only half of the loss as ordinary.","The loss is $150,000 - $30,000 = $120,000. The ordinary loss is limited to $100,000 on a joint return; the remaining $20,000 is a capital loss."],"wt":["trap","limit","concept",""],"tags":{"area":"IV","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Small business (section 1244) stock loss is ordinary up to $50,000 ($100,000 on a joint return); any excess is capital loss.","from":"2026-01-01","calc":1,"steps":["Loss = 150,000 - 30,000 = $120,000","Ordinary loss = lesser of $120,000 and 100,000 = $100,000"]}},{"i":"TCP-IV-B-0013","t":"Which taxpayer may claim an ordinary loss under the small business stock rules when the stock becomes worthless in 2026? Assume the issuing corporation qualified as a small business corporation when the stock was issued.","mc":{"s":"Which taxpayer may claim an ordinary loss under the small business stock rules when the stock becomes worthless in 2026? Assume the issuing corporation qualified as a small business corporation when the stock was issued.","d":"","o":["An individual who bought the same stock from another shareholder on a stock exchange","A corporation that bought newly issued stock directly from the small business corporation","An individual who bought newly issued stock for cash directly from the corporation","An individual who received newly issued stock from the corporation in exchange for services"],"a":3,"cite":"IRC §1244(a); IRC §1244(c)(1); Reg. §1.1244(a)-1","rat":"Ordinary loss treatment is available only to the individual (or partnership) that originally received the stock from the corporation for money or property.","ex":["The stock must be acquired by original issuance from the corporation, not from another shareholder.","Only individuals and partnerships are eligible; a corporate shareholder is not.","Ordinary loss treatment is available only to the individual (or partnership) that originally received the stock from the corporation for money or property.","The stock must be issued for money or other property, not for services."],"wt":["concept","concept","","concept"],"tags":{"area":"IV","group":"B","skill":"Application","diff":1},"asof":"2026-09-29","rl":"Ordinary loss on small business stock is limited to individuals and partnerships that acquired stock directly from the corporation for money or property.","from":"2026-01-01"}}],"7":[{"i":"TCP-IV-B-0008","t":"In 2026 Uma Tate sold land for $800,000 under the installment method. The buyer paid $100,000 in cash, assumed her $150,000 mortgage, and gave a note for the rest, payable in later years. Her basis in the land was $200,000. What gain does she recognize in 2026?","mc":{"s":"In 2026 Uma Tate sold land for $800,000 under the installment method. The buyer paid $100,000 in cash, assumed her $150,000 mortgage, and gave a note for the rest, payable in later years. Her basis in the land was $200,000. What gain does she recognize in 2026?","d":"","o":["$25,000","$69,231","$75,000","$92,308"],"a":4,"cite":"IRC §453(a); IRC §453(c); Reg. §15a.453-1(b)","rat":"The mortgage is less than her basis, so it is not a payment.","ex":["Uses the basis fraction of the price instead of the gross profit fraction.","Subtracts the assumed mortgage from gross profit.","Uses the selling price as the contract price. The assumed mortgage reduces the contract price when it does not exceed basis.","The mortgage is less than her basis, so it is not a payment. Contract price = $800,000 - $150,000 = $650,000; gross profit = $800,000 - $200,000 = $600,000; gross profit percentage = $600,000/$650,000. Gain = $100,000 x that percentage = $92,308."],"wt":["concept","concept","concept",""],"tags":{"area":"IV","group":"B","skill":"Application","diff":3},"asof":"2026-09-29","rl":"Under the installment method gain is recognized in proportion to payments received, using gross profit divided by contract price.","from":"2026-01-01","calc":1,"steps":["Contract price = 800,000 - 150,000 = $650,000","Gross profit = 800,000 - 200,000 = $600,000","Gain in 2026 = 100,000 x $600,000/$650,000 = $92,308"]}},{"i":"TCP-IV-B-0009","t":"Kit Alder sold business equipment on the installment method for $100,000, receiving $20,000 in 2026 and the balance in later years. The total gain is $90,000, of which $60,000 is depreciation recapture treated as ordinary income. How much gain must Kit report in 2026?","mc":{"s":"Kit Alder sold business equipment on the installment method for $100,000, receiving $20,000 in 2026 and the balance in later years. The total gain is $90,000, of which $60,000 is depreciation recapture treated as ordinary income. How much gain must Kit report in 2026?","d":"","o":["$18,000","$60,000","$66,000","$90,000"],"a":3,"cite":"IRC §453(i); IRC §1245; IRC §453(a)","rat":"Depreciation recapture, $60,000, is recognized entirely in the year of sale.","ex":["Spreads the entire gain, including the recapture, over the payments. Recapture income is recognized in the year of sale.","Reports only the recapture and omits the installment gain on the rest.","Depreciation recapture, $60,000, is recognized entirely in the year of sale. The remaining gain of $30,000 is reported ratably: $20,000/$100,000 = 20% of it is $6,000. Total $66,000.","Reports all of the gain in 2026 and ignores the installment method for the non-recapture part."],"wt":["concept","calc","","concept"],"tags":{"area":"IV","group":"B","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Depreciation recapture is recognized in the year of sale even on an installment sale; only the remaining gain is deferred.","from":"2026-01-01","calc":1,"steps":["Recapture = lesser of 90,000 and 60,000 = $60,000","Remaining gain = 90,000 - $60,000 = $30,000; 20% = $6,000","Total = $66,000"]}},{"i":"TCP-IV-B-0014","t":"Rae Bolt sold business equipment for $300,000. She bought it for $250,000 and has claimed $150,000 of depreciation, so its adjusted basis is $100,000. Plan 1: take the full $300,000 in the year of sale. Plan 2: take $60,000 in the year of sale and $60,000 in each of the next four years, using the installment method with adequate stated interest. Assume ordinary income is taxed at 35% and long-term capital gain at 20%, and ignore interest. How much less tax does Rae pay in the year of sale under Plan 2 than under Plan 1?","mc":{"s":"Rae Bolt sold business equipment for $300,000. She bought it for $250,000 and has claimed $150,000 of depreciation, so its adjusted basis is $100,000. Plan 1: take the full $300,000 in the year of sale. Plan 2: take $60,000 in the year of sale and $60,000 in each of the next four years, using the installment method with adequate stated interest. Assume ordinary income is taxed at 35% and long-term capital gain at 20%, and ignore interest. How much less tax does Rae pay in the year of sale under Plan 2 than under Plan 1?","d":"","o":["$8,000","$14,000","$48,500","$62,500"],"a":1,"cite":"IRC §453(i); IRC §1245(a); IRC §453(c)","rat":"The gain is $200,000: $150,000 of depreciation recapture (ordinary) and $50,000 of long-term capital gain.","ex":["The gain is $200,000: $150,000 of depreciation recapture (ordinary) and $50,000 of long-term capital gain. Recapture income is recognized in the year of sale even on the installment method, and it is added to her basis for the installment computation. The remaining $50,000 gain is reported as payments come in: 50,000 / 300,000 x $60,000 = $10,000 in the year of sale. Plan 2 defers $40,000 of capital gain, saving $8,000.","Assumes that the deferred $40,000 is taxed at the ordinary rate. Recapture is not deferred; the deferred gain is the capital gain part, taxed at 20%.","Spreads the whole $200,000 gain by the 66.7% gross profit ratio and taxes the $40,000 reported in the year of sale as recapture income. Recapture must be recognized in full in the year of sale, and only the capital gain is spread.","This is the year-of-sale tax under Plan 1 ($62,500), not the difference between the plans."],"wt":["","concept","concept","trap"],"tags":{"area":"IV","group":"B","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"On an installment sale, depreciation recapture is recognized in the year of sale, and only the remaining gain can be spread over the payments.","from":"2026-01-01","calc":1,"steps":["Gain = 300,000 - 100,000 = 200,000; recapture = min(200,000, 150,000) = 150,000 (ordinary); remaining gain = 50,000","Plan 1: tax = 150,000 x 35% + 50,000 x 20% = 62,500","Plan 2: adjusted basis after recapture = 250,000; gross profit percentage = 50,000 / 300,000; year of sale gain = 60,000 x 50,000 / 300,000 = 10,000; tax = 52,500 + 2,000 = 54,500","Difference = 62,500 - 54,500 = 8,000"]}}],"8":[{"i":"TCP-IV-C-0001","t":"Which pair of persons is related under the rules that disallow losses on sales between related persons?","mc":{"s":"Which pair of persons is related under the rules that disallow losses on sales between related persons?","d":"","o":["An individual and his uncle","An individual and his first cousin","An individual and his wife's brother","An individual and his brother"],"a":4,"cite":"IRC §267(b)(1); IRC §267(c)(4); Reg. §1.267(c)-1","rat":"Brothers and sisters are members of an individual's family for the related-party rules.","ex":["An uncle is not within the family definition, which covers siblings, spouse, ancestors and lineal descendants.","A cousin is not a family member for these rules.","In-laws are not included in the family definition.","Brothers and sisters are members of an individual's family for the related-party rules."],"wt":["concept","concept","concept",""],"tags":{"area":"IV","group":"C","skill":"Remembering & Understanding","diff":1},"asof":"2026-09-29","rl":"For loss disallowance, family includes siblings, spouse, ancestors and lineal descendants; uncles, cousins and in-laws are not included.","from":"2026-01-01"}},{"i":"TCP-IV-C-0003","t":"Elm Street Corp. is an accrual-basis calendar-year corporation. It owes $50,000 of interest for 2026 to Ted Ross, a cash-basis individual who owns 60% of its stock. Elm accrued the interest on December 31, 2026 and paid it on March 1, 2027. How much of the interest may Elm deduct for 2026?","mc":{"s":"Elm Street Corp. is an accrual-basis calendar-year corporation. It owes $50,000 of interest for 2026 to Ted Ross, a cash-basis individual who owns 60% of its stock. Elm accrued the interest on December 31, 2026 and paid it on March 1, 2027. How much of the interest may Elm deduct for 2026?","d":"","o":["$0","$20,000","$30,000","$50,000"],"a":1,"cite":"IRC §267(a)(2); IRC §267(b)(2); Reg. §1.267(a)-1(b)","rat":"Deductions for amounts owed to a related cash-basis person are deferred until the payee includes the amount in income.","ex":["Deductions for amounts owed to a related cash-basis person are deferred until the payee includes the amount in income. Ted, a cash-basis owner of more than 50%, is taxed when paid in 2027, so Elm's deduction also waits until 2027.","Allows the part owed as if to other shareholders; the amount is owed only to Ted.","Allows only the part equal to Ted's ownership percentage; the whole amount is deferred.","Allows the deduction when accrued. Accrual-basis deductions to a related cash-basis owner wait until payment."],"wt":["","calc","calc","concept"],"tags":{"area":"IV","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"An accrual-basis payor deducts amounts owed to a related cash-basis payee only when the payee includes them in income.","from":"2026-01-01","calc":1,"steps":["Related party (owner of more than 50%): deduction deferred to the year of payment","2026 deduction = $0; the deduction belongs in 2027"]}}],"9":[{"i":"TCP-IV-C-0002","t":"Al Cruz directly owns 30% of the stock of Cruz Tools, Inc. His wife owns 10%, his brother owns 15%, his uncle owns 20%, and unrelated persons own the rest. What percentage of Cruz Tools does Al own directly and constructively in testing whether he is related to the corporation?","mc":{"s":"Al Cruz directly owns 30% of the stock of Cruz Tools, Inc. His wife owns 10%, his brother owns 15%, his uncle owns 20%, and unrelated persons own the rest. What percentage of Cruz Tools does Al own directly and constructively in testing whether he is related to the corporation?","d":"","o":["30%","40%","55%","75%"],"a":3,"cite":"IRC §267(c)(2); IRC §267(c)(4); IRC §267(b)(2)","rat":"Stock owned by his spouse and brother is attributed to Al: 30% + 10% + 15% = 55%.","ex":["Counts only direct ownership. Family stock is also attributed.","Attributes the wife's stock but leaves out the brother's, who is also a member of the family.","Stock owned by his spouse and brother is attributed to Al: 30% + 10% + 15% = 55%. The uncle's stock is not attributed.","Includes the uncle's stock, but an uncle is not a family member for attribution."],"wt":["concept","concept","","concept"],"tags":{"area":"IV","group":"C","skill":"Application","diff":3},"asof":"2026-09-29","rl":"An individual is treated as owning stock owned by his spouse, siblings, ancestors and lineal descendants; more than 50% ownership makes a corporation related.","from":"2026-01-01","calc":1,"steps":["Direct 30% + wife 10% + brother 15% = 55%","Uncle's stock is not attributed"]}},{"i":"TCP-IV-C-0007","t":"Each of the following taxpayers sells property at a loss to the buyer described. In which case is the loss disallowed under the related-party rules?","mc":{"s":"Each of the following taxpayers sells property at a loss to the buyer described. In which case is the loss disallowed under the related-party rules?","d":"","o":["Vera sells stock to a corporation in which she owns 60% of the value","Wade sells stock to a partnership in which he owns exactly 50% of the capital and profits","Xena sells stock to her first cousin","Yale sells stock to a corporation in which he owns 45% and his first cousin owns 5%"],"a":1,"cite":"IRC §267(a)(1); IRC §267(b)(2); IRC §707(b)(1)","rat":"An individual and a corporation are related if the individual owns, directly or constructively, more than 50% of the corporation's value.","ex":["An individual and a corporation are related if the individual owns, directly or constructively, more than 50% of the corporation's value.","The relationship rule requires more than 50%, so 50% does not make the partnership related.","A first cousin is not a family member for the loss disallowance rules.","The cousin's stock is not attributed, so he owns only 45%, not more than 50%."],"wt":["","limit","concept","limit"],"tags":{"area":"IV","group":"C","skill":"Application","diff":1},"asof":"2026-09-29","rl":"Losses are disallowed between an individual and an entity in which the individual owns more than 50% directly or through family attribution.","from":"2026-01-01"}},{"i":"TCP-IV-C-0008","t":"Ana Cole sells depreciable equipment with an adjusted basis of $60,000 to a corporation of which she owns 60% of the stock, for its fair market value of $100,000. She has held the equipment for many years. What is the amount and character of her gain?","mc":{"s":"Ana Cole sells depreciable equipment with an adjusted basis of $60,000 to a corporation of which she owns 60% of the stock, for its fair market value of $100,000. She has held the equipment for many years. What is the amount and character of her gain?","d":"","o":["$40,000 of section 1231 gain","$40,000 of ordinary income","$40,000 of short-term capital gain","$100,000 of ordinary income"],"a":2,"cite":"IRC §1239(a); IRC §1239(b); IRC §267(c)","rat":"A gain on the sale of depreciable property between a taxpayer and a controlled entity (more than 50%) is ordinary.","ex":["Would apply in an unrelated sale of business equipment. A sale to a controlled entity is ordinary.","A gain on the sale of depreciable property between a taxpayer and a controlled entity (more than 50%) is ordinary. The gain is $100,000 - $60,000 = $40,000.","The equipment was held for many years, and the gain is ordinary rather than short-term capital gain.","Treats the entire selling price as ordinary income. Only the gain is income."],"wt":["concept","","concept","calc"],"tags":{"area":"IV","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Gain on a sale of depreciable property to a controlled entity is ordinary income, regardless of holding period.","from":"2026-01-01","calc":1,"steps":["Gain = 100,000 - 60,000 = $40,000","Character: ordinary"]}},{"i":"TCP-IV-C-0009","t":"Nilo Corp. is an accrual-basis, calendar-year C corporation taxed at 21%. At December 31, 2026 it owes year-end bonuses that are fixed and unconditional: $60,000 to Mira, who owns 60% of its stock and uses the cash method, and $90,000 to employees who own no stock. Plan 1: pay all bonuses on February 15, 2027. Plan 2: pay Mira's bonus on December 28, 2026 and the other bonuses on February 15, 2027. How much lower is Nilo's 2026 federal income tax under Plan 2 than under Plan 1?","mc":{"s":"Nilo Corp. is an accrual-basis, calendar-year C corporation taxed at 21%. At December 31, 2026 it owes year-end bonuses that are fixed and unconditional: $60,000 to Mira, who owns 60% of its stock and uses the cash method, and $90,000 to employees who own no stock. Plan 1: pay all bonuses on February 15, 2027. Plan 2: pay Mira's bonus on December 28, 2026 and the other bonuses on February 15, 2027. How much lower is Nilo's 2026 federal income tax under Plan 2 than under Plan 1?","d":"","o":["$0","$12,600","$18,900","$31,500"],"a":2,"cite":"IRC §267(a)(2); IRC §267(b)(2); IRC §404(a)(5); Reg. §1.404(b)-1T","rat":"Bonuses to unrelated employees paid within 2 1/2 months after year-end are deductible in 2026.","ex":["Assumes all bonuses are deductible in 2026 if paid within 2 1/2 months. That rule does not apply to amounts owed to a related cash-basis person.","Bonuses to unrelated employees paid within 2 1/2 months after year-end are deductible in 2026. Mira owns more than 50%, so an amount owed to her is deductible only when she includes it in income; a February payment is deductible in 2027. Under Plan 1 the 2026 deduction is $90,000; under Plan 2 it is $150,000. The extra $60,000 deduction saves $12,600.","This is the value of the deduction for the unrelated employees, which is available under both plans.","This is the total 2026 tax reduction under Plan 2, not the difference. The $90,000 of unrelated bonuses is deductible in 2026 under both plans."],"wt":["concept","","calc","trap"],"tags":{"area":"IV","group":"C","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"An accrual-basis payer may deduct an amount owed to a related cash-basis person only when the payee includes it in income, so the 2 1/2 month rule for bonuses does not help with a more-than-50% shareholder.","from":"2026-01-01","calc":1,"steps":["Mira owns 60% (over 50%), so she is a related person","Plan 1: 2026 deduction = 90,000 (unrelated bonuses paid within 2 1/2 months); Mira's 60,000 is deductible in 2027","Plan 2: 2026 deduction = 90,000 + 60,000 = 150,000","Extra deduction = 60,000; tax = 60,000 x 21% = 12,600"]}}],"10":[{"i":"TCP-IV-C-0004","t":"Nan Tsai sold stock with a basis of $100,000 to her brother Ivo for $70,000, its fair market value, and her $30,000 loss was disallowed. Ivo later sold the stock to an unrelated buyer for $50,000. What loss does Ivo recognize on the later sale?","mc":{"s":"Nan Tsai sold stock with a basis of $100,000 to her brother Ivo for $70,000, its fair market value, and her $30,000 loss was disallowed. Ivo later sold the stock to an unrelated buyer for $50,000. What loss does Ivo recognize on the later sale?","d":"","o":["$0","$20,000","$30,000","$50,000"],"a":2,"cite":"IRC §267(d); IRC §1012; Reg. §1.267(d)-1(a)","rat":"Ivo's basis is his cost, $70,000.","ex":["Assumes no loss is allowed to Ivo because of Nan's earlier sale. Ivo's own loss is allowed.","Ivo's basis is his cost, $70,000. His loss is $70,000 - $50,000 = $20,000. Nan's disallowed loss does not increase his loss.","Uses Nan's disallowed loss as Ivo's loss.","Uses Nan's original basis, which increases Ivo's loss by her disallowed loss. Disallowed losses can only offset gain."],"wt":["concept","","trap","concept"],"tags":{"area":"IV","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"A related-party buyer's own loss on a later sale is allowed, and the seller's disallowed loss cannot increase it.","from":"2026-01-01","calc":1,"steps":["Ivo's basis = 70,000","Loss = 70,000 - 50,000 = $20,000"]}},{"i":"TCP-IV-C-0010","t":"Ann Kohl sells rental land with a basis of $100,000 to her daughter Beth for $500,000. Beth pays $100,000 at closing and gives a note for $400,000 payable in four equal annual installments, and Ann uses the installment method. Plan 1: Beth resells the land to an unrelated buyer for $550,000 in the same year. Plan 2: Beth resells it to an unrelated buyer for $550,000 after holding it for three years. How much more of Ann's gain is recognized in the year of the sale to Beth under Plan 1 than under Plan 2?","mc":{"s":"Ann Kohl sells rental land with a basis of $100,000 to her daughter Beth for $500,000. Beth pays $100,000 at closing and gives a note for $400,000 payable in four equal annual installments, and Ann uses the installment method. Plan 1: Beth resells the land to an unrelated buyer for $550,000 in the same year. Plan 2: Beth resells it to an unrelated buyer for $550,000 after holding it for three years. How much more of Ann's gain is recognized in the year of the sale to Beth under Plan 1 than under Plan 2?","d":"","o":["$80,000","$320,000","$360,000","$400,000"],"a":2,"cite":"IRC §453(e)(1); IRC §453(e)(2); IRC §453(f)(1)","rat":"The gross profit percentage is $400,000 / $500,000 = 80%.","ex":["This is Ann's gain in the sale year under Plan 2 ($80,000), not the additional gain under Plan 1.","The gross profit percentage is $400,000 / $500,000 = 80%. Under Plan 2 only the $100,000 down payment is received in the sale year, so gain is $80,000. Under Plan 1, a resale by the related buyer within two years is treated as a payment to Ann of the lesser of the amount realized ($550,000) or the total contract price ($500,000), less payments already received: another $400,000, so all of the gain is recognized: 80% x $500,000 = $400,000. The difference is $320,000.","Uses the resale price of $550,000 as the deemed payment. The deemed payment is limited to the total contract price, $500,000, less the payments already received.","This is all of Ann's gain in the sale year under Plan 1. Under Plan 2 she already recognizes $80,000 in that year, so the additional gain is $320,000."],"wt":["trap","","calc","trap"],"tags":{"area":"IV","group":"C","skill":"Analysis","diff":3},"asof":"2026-09-29","rl":"If a related buyer resells installment property within two years, the seller treats the lesser of the resale amount realized or the total contract price, less payments received, as received at the resale, which accelerates the gain.","from":"2026-01-01","calc":1,"steps":["Gross profit percentage = (500,000 - 100,000) / 500,000 = 80%","Plan 2: sale year payment 100,000, gain = 100,000 x 80% = 80,000","Plan 1: deemed payment = min(550,000, 500,000) - 100,000 = 400,000; sale year payments = 500,000; gain = 500,000 x 80% = 400,000","Difference = 400,000 - 80,000 = 320,000"]}}],"11":[{"i":"TCP-IV-C-0005","t":"On January 1, 2026, Trellis Group Corp. lends an employee $200,000 on a demand note that bears no interest. The loan is made in connection with the employee's services and remains outstanding all year. Assume the applicable rate is 4.0%. What amount is treated as additional compensation to the employee for 2026?","mc":{"s":"On January 1, 2026, Trellis Group Corp. lends an employee $200,000 on a demand note that bears no interest. The loan is made in connection with the employee's services and remains outstanding all year. Assume the applicable rate is 4.0%. What amount is treated as additional compensation to the employee for 2026?","d":"","o":["$2,000","$8,000","$16,000","$200,000"],"a":2,"cite":"IRC §7872(a)(1); IRC §7872(c)(1)(B); Reg. §1.7872-4","rat":"A below-market compensation-related loan creates imputed interest at the applicable rate.","ex":["Uses one quarter of the year's foregone interest.","A below-market compensation-related loan creates imputed interest at the applicable rate. The foregone interest, $200,000 x 4.0% = $8,000, is treated as paid to the employee as compensation and then paid back as interest.","Uses two years of foregone interest.","Treats the entire loan as compensation."],"wt":["calc","","calc","concept"],"tags":{"area":"IV","group":"C","skill":"Application","diff":2},"asof":"2026-09-29","rl":"Foregone interest on a below-market compensation-related loan is treated as compensation to the employee and interest paid back to the employer.","from":"2026-01-01","calc":1,"steps":["Foregone interest = 200,000 x 4.0% = $8,000"]}},{"i":"TCP-IV-C-0006","t":"On January 1, 2026, Vic Amaro sold land for $500,000, payable in one lump sum in two years, with no stated interest. Assume the applicable federal rate is 4.0% compounded annually. Vic is an accrual-basis taxpayer for interest. How much interest income must he report for 2026?","mc":{"s":"On January 1, 2026, Vic Amaro sold land for $500,000, payable in one lump sum in two years, with no stated interest. Assume the applicable federal rate is 4.0% compounded annually. Vic is an accrual-basis taxpayer for interest. How much interest income must he report for 2026?","d":"","o":["$0","$18,491","$20,000","$37,722"],"a":2,"cite":"IRC §1274(a); IRC §1272(a); IRC §483","rat":"The sale has unstated interest.","ex":["Assumes no interest is reportable because no interest is stated. Unstated interest is imputed.","The sale has unstated interest. Issue price = present value = $500,000 / 1.04^2 = $462,278. Interest accrued in the first year is $462,278 x 4.0% = $18,491.","Applies the rate to the stated payment instead of its present value.","Reports the entire unstated interest in the first year instead of accruing it over the term."],"wt":["concept","","calc","concept"],"tags":{"area":"IV","group":"C","skill":"Application","diff":3},"asof":"2026-09-29","rl":"When a sale has too little stated interest, part of the payment is recharacterized as interest that accrues at the applicable rate.","from":"2026-01-01","calc":1,"steps":["Present value = 500,000 / 1.04^2 = $462,278","First-year interest = $462,278 x 4.0% = $18,491"]}}]};
window.PAIRS=[];
